// devices.siteDevices.read — a project's devices for the site page. Generated by `pnpm gen:query`; acceptance
// cases added.
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, createTestDatabase, runAsOwner, type TestDatabase } from '@ocs/testing';
import { Forbidden, grantOf, openTestKernel, systemActor, type TestKernel } from '../../kernel/index.ts';
import { createClient, createSite } from '../../org/index.ts';
import { registerDevice } from '../commands/register-device.ts';
import { syncDevices } from '../commands/sync-devices.ts';
import { siteDevices } from '../queries/site-devices.ts';

const pm = aStaffActor({ roles: ['pm'] });
const sync = systemActor('device-platform');
let testDb: TestDatabase;
let t: TestKernel;
let siteA: string;

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url);
  const setup = aStaffActor({ roles: ['director'] });
  t.grant(setup, createClient.permission, createSite.permission);
  t.grant(pm, siteDevices.permission, registerDevice.permission);
  t.grant(sync, syncDevices.permission);
  const a = await t.kernel.execute(createClient, setup, { shortCode: 'CLIENTA', name: 'Client A' }, 'test');
  const place = { countryCode: 'ES', cityCode: 'MAD', cityName: 'Madrid', name: 'Mall A', standard: 'L' };
  ({ id: siteA } = await t.kernel.execute(createSite, setup, { clientId: a.id, ...place }, 'test'));
  await runAsOwner(testDb.url, `UPDATE site SET platform_ref = 'mall-a' WHERE id = $1`, [siteA]);
  await runAsOwner(
    testDb.url,
    `INSERT INTO zone (id, client_id, site_id, kind, platform_ref, name)
     SELECT gen_random_uuid(), client_id, id, 'gate', 'gate-1', 'Gate 1' FROM site WHERE id = $1`,
    [siteA],
  );
  await t.kernel.execute(registerDevice, pm, { siteId: siteA, sn: 'SN-0009', model: 'G6' }, 'test');
  const devices = [
    {
      sn: 'SN-0001',
      model: 'G6-8MA',
      status: 'offline',
      channels: [
        { no: 1, gateRef: 'gate-1' },
        { no: 2, gateRef: null },
      ],
    },
  ];
  await t.kernel.execute(syncDevices, sync, { siteId: siteA, devices }, 'system');
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('devices.siteDevices.read', () => {
  it('is for staff roles, not clients, partners or the system', async () => {
    expect(grantOf(siteDevices.permission)?.roles).not.toContain('client');
    expect(grantOf(siteDevices.permission)?.roles).not.toContain('partner');
    await expect(t.kernel.read(siteDevices, aStaffActor(), { siteId: siteA })).rejects.toBeInstanceOf(
      Forbidden,
    );
  });

  it("lists the project's devices with platform status, offline since, registration and channel gates", async () => {
    const list = await t.kernel.read(siteDevices, pm, { siteId: siteA });
    expect(list.map((d) => [d.sn, d.platformStatus, d.offlineSince !== null, d.registered])).toEqual([
      ['SN-0001', 'offline', true, false],
      ['SN-0009', null, false, true],
    ]);
    expect(list[0]?.channels).toEqual([
      { no: 1, gate: 'Gate 1' },
      { no: 2, gate: null },
    ]);
  });
});
